def is_palindrome_ignore_non_alnum(s):
    filtered = list(map(str.lower, filter(str.isalnum, s)))
    left, right = 0, len(filtered) - 1
    while left < right:
        if filtered[left] != filtered[right]:
            return False
        left += 1
        right -= 1
    return True

