def max_sum_non_adjacent(lst):
    n = len(lst)
    if n == 0:
        return 0
    dp = [0] * (n + 1)
    dp[1] = max(lst[0], 0)
    for i in range(2, n + 1):
        dp[i] = max(dp[i - 1], dp[i - 2] + lst[i - 1])
    return dp[n]

