from functools import cmp_to_key

def sort_by_reversed_string(words):
    def compare(word_a, word_b):
        rev_a, rev_b = word_a[::-1], word_b[::-1]
        if rev_a < rev_b:
            return -1
        elif rev_a > rev_b:
            return 1
        return 0
    return sorted(words, key=cmp_to_key(compare))

def char_count_difference(a, b):
    counts = {}
    for ch in a:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in b:
        counts[ch] = counts.get(ch, 0) - 1
    return sum(abs(v) for v in counts.values())

def count_armstrong_in_range(a, b):
    total = 0
    x = a
    while x <= b:
        digits = str(x)
        k = len(digits)
        if x == sum(int(ch) ** k for ch in digits):
            total += 1
        x += 1
    return total

def total_break_minutes(schedule):
    if len(schedule) < 2:
        return 0
    total = 0
    for (_, prev_end), (curr_start, _) in zip(schedule, schedule[1:]):
        total += curr_start - prev_end
    return total

