def duration_to_minutes(duration_str):
    total_minutes = 0
    number = ''
    for ch in duration_str:
        if ch.isdigit():
            number += ch
        elif ch == 'h':
            total_minutes += int(number) * 60
            number = ''
        elif ch == 'm':
            total_minutes += int(number)
            number = ''
    return total_minutes

