from bisect import bisect_left, bisect_right

def percentile_of_value_among_duplicates(scores, value):
    s = sorted(scores)
    less = bisect_left(s, value)
    equal = bisect_right(s, value) - less
    return round((less + equal / 2) / len(s) * 100, 2)

def sort_by_sign_then_value(nums):
    pos, zero, neg = [], [], []
    for x in nums:
        if x > 0:
            pos.append(x)
        elif x == 0:
            zero.append(x)
        else:
            neg.append(x)
    pos.sort()
    neg.sort(reverse=True)
    return pos + zero + neg

